# Comprehensive list of products covering all 26 categories with authentic details
products = []

def add_p(name, brand, category, subcat, size, mrp, price, img, desc, keywords, featured=False, bestseller=False, deal=False, badge=None, stock=50, rating=4.5, reviews=120):
    discount = round(((mrp - price) / mrp) * 100) if mrp > price else 0
    savings = round(mrp - price, 2)
    pid = f"fn_{len(products) + 1:03d}"
    products.append({
        "id": pid,
        "name": name,
        "brand": brand,
        "category": category,
        "subcategory": subcat,
        "sizeWeight": size,
        "mrp": float(mrp),
        "sellingPrice": float(price),
        "discount": discount,
        "savingsAmount": savings,
        "stock": stock,
        "rating": rating,
        "reviewsCount": reviews,
        "imageUrl": img,
        "description": desc,
        "searchKeywords": keywords + [name.lower(), brand.lower(), category.lower(), subcat.lower()],
        "isFeatured": featured,
        "isBestseller": bestseller,
        "isDeal": deal,
        "badge": badge or ("Best Price" if discount >= 15 else ("Today's Deal" if deal else ("Great Value" if discount >= 8 else None)))
    })

